boundary_profile.program:
BEGIN
{
    printf("constructor-probe-ready\n");
}

uprobe:/tmp/fclones-ssd-zkMtjG7M/profile-target/release/fclones:*new_with_specifics*
/pid == cpid/
{
    @started[tid] = nsecs;
}

uretprobe:/tmp/fclones-ssd-zkMtjG7M/profile-target/release/fclones:*new_with_specifics*
/pid == cpid && @started[tid]/
{
    $duration = nsecs - @started[tid];
    @calls = count();
    @duration_ns = sum($duration);
    @duration_histogram_us = hist($duration / 1000);
    delete(@started[tid]);
}

END
{
    print(@calls);
    print(@duration_ns);
    print(@duration_histogram_us);
    clear(@calls);
    clear(@duration_ns);
    clear(@duration_histogram_us);
    clear(@started);
}
